:root {
  --bg: #ffffff;
  --header-bg: #2d6a4f;
  --header-text: #ffffff;
  --badge-bg: #95d5b2;
  --badge-text: #1b4332;
  --label-color: #6b7280;
  --value-color: #111827;
  --divider: #e5e7eb;
  --footer-bg: #f0fdf4;
  --footer-text: #2d6a4f;
  --amount-color: #1b4332;
}

.reservation-card {
  background: var(--bg);
  border-radius: 14px;
  overflow: hidden;
  width: 320px;
  border: 1px solid var(--divider);
}

.card-header {
  background: var(--header-bg);
  padding: 16px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.card-title {
  color: var(--header-text);
  font-size: 16px;
  font-weight: 700;
  margin: 0;
}

.card-body {
  padding: 12px 20px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid var(--divider);
}

.detail-row:last-child {
  border-bottom: none;
}

.label {
  font-size: 13px;
  color: var(--label-color);
  font-weight: 500;
}

.value {
  font-size: 13px;
  color: var(--value-color);
  font-weight: 600;
}

.card-footer {
  background: var(--footer-bg);
  padding: 12px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--divider);
}

.total-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--footer-text);
}

.total-amount {
  font-size: 20px;
  font-weight: 800;
  color: var(--amount-color);
}
